mapper.select:
with temp as ( select user_id, org_id, main_job from user_org
and main_job = 1
and user_id in
#{uid}
group by user_id, org_id, main_job
) select temp.user_id, temp.org_id, temp.main_job, o.forbidden as org_forbidden, o.node_name as org_name, o.id_path, o.node_category from temp join org_tree o on temp.org_id = o.id
o.forbidden = #{forbidden}

mapper.update:
update user_org
set main_job=1
where user_id = #{userId}
and org_id = #{orgId}

update user_org
set main_job=0
where user_id = #{userId}
and org_id != #{orgId}
and main_job = 1

mapper.select:
select distinct org_id
from user_org
where user_id = #{userId}
